from pathlib import Path
p=Path('work/pdf_engine.py');s=p.read_text();s=s.replace("if kind in ['numberline','doubleline']:","if kind == 'doubleline' and len(vals)>=2:\n  n=m.get('multiples',5); n=min(n,10)\n  for row in range(2):\n   yy=y+h*(.65 if row==0 else .15); c.line(x+8,yy,x+w-8,yy)\n   t(labels[row] if len(labels)>row else '',x,yy+25,w,10)\n   for i in range(n+1):\n    xx=x+8+(w-16)*i/n;c.line(xx,yy-4,xx,yy+4)\n    if n<=5 or i%2==0:t(str(vals[row]*i),xx-6,yy-15,40,8.5)\n elif kind == 'ratio' and isinstance(m.get('rows'),list):\n  rr=m['rows'];cw=(w-10)/2;rh=min(25,(h-25)/(len(rr)+1));yy=y+h-25\n  for j,row in enumerate([labels]+rr):\n   for i,v in enumerate(row[:2]):c.rect(x+i*cw,yy-j*rh,cw,rh);t(str(v),x+i*cw+5,yy-j*rh+rh/2-3,cw-10,10)\n elif kind == 'area' and 'rows' in m:\n  nr=m['rows'];nc=m['cols'];hh=min(h-18,w*.45);ww=min(w-12,hh*1.8);yy=y+8;cw=ww/nc;rh=hh/nr\n  for j in range(nr):\n   for i in range(nc):\n    c.rect(x+i*cw,yy+j*rh,cw,rh)\n    if j<m.get('shade_rows',0) and i<m.get('shade_cols',0):\n     c.line(x+i*cw+2,yy+j*rh+2,x+(i+1)*cw-2,yy+(j+1)*rh-2)\n elif kind == 'tape' and len(vals)>=2:\n  mx=max(vals);unit=(w-16)/mx;bh=min(27,h*.25)\n  for j,n in enumerate(vals[:2]):\n   yy=y+h*.60-j*(bh+27)\n   for i in range(int(n)):c.rect(x+8+i*unit,yy,unit,bh)\n   t(labels[j] if len(labels)>j else str(n),x+8,yy+bh+8,w-16,10)\n elif kind in ['numberline','doubleline']:")
s=s.replace("if i in [0,n] or n<=5:t(str(round(lo+(hi-lo)*i/n,2)),xx-8,yy-17,35,9)","if i in [0,n] or n<=5:t(str(round(lo+(hi-lo)*i/n,2)),xx-8,yy-17,35,9)\n   for j,v in enumerate(vals):\n    if isinstance(v,(int,float)) and lo<=v<=hi:\n     xx=x+12+(w-24)*(v-lo)/(hi-lo);c.circle(xx,yy,2,fill=1);t(labels[j] if len(labels)>j else str(v),xx-10,yy+15,70,9)")
p.write_text(s)
